/* generated by tools/make_voices.py: voice sprite timings and lip-sync envelopes (30 fps) */
const VOICE_DATA = {"file":"voice/ep10.mp3","lines":{"ep10_001":{"who":"TAKUTO","text":"Previously. In Saint Lumen, the Golden Saint asked me to wear the gold. I said no.","mono":true,"off":0.25,"dur":5.269,"env":"012777525698342134432100256434369742136775554443431268775144533334555410015675342004432432344554142125687421100000000000000025544335662234556632100000000000000"},"ep10_002":{"who":"TAKUTO","text":"I found Haruki. He does not want to come home. He is helping Lucien build a road there instead.","mono":true,"off":5.9193,"dur":6.187,"env":"000566221897776432478875566410112321111000000000554854467786224564321021554442367764210000000000000057754236993017554445653553454312666524532257887653113433333323441165431100000000000000"},"ep10_003":{"who":"TAKUTO","text":"The road costs light. Brands. The people who pay it go grey, and cold.","mono":true,"off":12.506,"dur":4.565,"env":"01433789995102267634333133576421000000000000366655432111222000013022453026533520224445421024442112454543332112320211156543211000000000000"},"ep10_004":{"who":"TAKUTO","text":"And I put a crack in a wall that nothing has ever broken.","mono":true,"off":17.4713,"dur":3.285,"env":"001579960197930132788763012555533689997543210354124677751135445656413442442126665201120000000000000"},"ep10_005":{"who":"SABLE","text":"Wake up, old friend. Six years is a long nap, even for a Calamity.","mono":false,"off":21.1567,"dur":5.035,"env":"00038942486301432311110135433221110000000001367754124532223333322343333444544444333332100100000234321221011221011122322322112211000000000000000000000000"},"ep10_006":{"who":"SABLE","text":"Your favourite Hunter is very close. The one who got away.","mono":false,"off":26.5913,"dur":4.075,"env":"000139832236778525421224544234233211235412444431111355322124665310110133357674542344531133344343331000000000000000000000000"},"ep10_007":{"who":"HUNTER","text":"Saint! A rider from the plains. A horde, two days out. Thousands. Lesser Fiends, mostly.","mono":false,"off":31.066,"dur":5.312,"env":"0012776446547899864740014433101154333332221000210255554100124224443213443321000000004555543112221110000024412132000233332221001232321100111100000000000000000000"},"ep10_008":{"who":"HUNTER","text":"And something at the back of them. Bigger than a hill.","mono":false,"off":36.778,"dur":3.285,"env":"003423379653046544303312777630013100122222110000003653125554223222220003443221110000000000000000000"},"ep10_009":{"who":"SIEG","text":"Morvudd.","mono":false,"off":40.4633,"dur":0.875,"env":"069866666667655543431100000"},"ep10_010":{"who":"LUCIEN","text":"You are certain?","mono":false,"off":41.738,"dur":1.152,"env":"02599898643333498776300354432210000"},"ep10_011":{"who":"SIEG","text":"Nothing else walks behind a horde. Morvudd does not lead. It drives.","mono":false,"off":43.29,"dur":4.523,"env":"1875214765314655433138865313310376676656644865654432000000000059876656654431576546865541026776666543210000000075213698655544433213322000"},"ep10_012":{"who":"LUCIEN","text":"Then the Order holds the walls of Saint Lumen. My Sanctum covers the city. Nothing will pass it.","mono":false,"off":48.2127,"dur":5.781,"env":"027977776535888377521476654222006533466665544223412226653124776554222100000000000006765332286654001544402168325532003332227734322100000005798410364443553001246543222222100000"},"ep10_013":{"who":"RIN","text":"And the villages on the plains? There are six of them between here and the horde.","mono":false,"off":54.394,"dur":4.117,"env":"0479973299798313587533666666101166665444333222100000027897444337401225214655415121355553102555444223444200355432210000000000"},"ep10_014":{"who":"LUCIEN","text":"We will open the gates to anyone who reaches them.","mono":false,"off":58.9113,"dur":2.603,"env":"0599698317995006566521168663114203610367666645554335653675203335333024322210000"},"ep10_015":{"who":"RIN","text":"They will not reach them. Not in two days. Not with children.","mono":false,"off":61.914,"dur":3.456,"env":"05895599888887620257410342045444320000025788742266743316651585544432324556520441103425543124322100000000"},"ep10_016":{"who":"SIEG","text":"Then someone holds the plains road. At the old stone bridge. Long enough for the villages to run.","mono":false,"off":65.77,"dur":5.952,"env":"09877543386555665563597656653300630168777776643467766654333100000000006730793157666524440187666666523876754322343100000000049987666666553000475765776765345665430277667755432211000"},"ep10_017":{"who":"LUCIEN","text":"That someone will die, Sieg.","mono":false,"off":72.122,"dur":1.685,"env":"018971133796677765664214975555542332366543210110000"},"ep10_018":{"who":"SIEG","text":"Probably.","mono":false,"off":74.2073,"dur":0.917,"env":"0389766756765677765555310000"},"ep10_019":{"who":"TAKUTO","text":"We go with him.","mono":false,"off":75.5247,"dur":1.024,"env":"0343128999854651124322110000000"},"ep10_020":{"who":"LUCIEN","text":"Haruki stays. The Rite needs him.","mono":false,"off":76.9487,"dur":2.325,"env":"0026998678730126543331286555444232000077559776411467866523324322211000"},"ep10_021":{"who":"HARUKI","text":"Lucien, I could freeze the front of the horde. Three seconds at a time. It would save...","mono":false,"off":79.674,"dur":4.309,"env":"0479987432866425762176421116666652263017866534653167765322110000000000179775435871166557565322776665443025345424335765432210000000"},"ep10_022":{"who":"LUCIEN","text":"You stay, Haruki. That is not a request.","mono":false,"off":84.3833,"dur":2.709,"env":"0379544149876654326876678720114644321000001876256435986656744640021887431133101000"},"ep10_023":{"who":"HARUKI","text":"...Yes, Saint.","mono":false,"off":87.4927,"dur":1.088,"env":"058999996423259887666323433200000"},"ep10_024":{"who":"AKURO","text":"Not a request. Did you hear how fast his voice went cold, boy?","mono":true,"off":88.9807,"dur":4.715,"env":"0157887666689775456641115577531123210000013443466335796333466675311136765654222244322246799665433123665320001113678554433211014656543321110000"},"ep10_025":{"who":"HARUKI","text":"You asked me what consecrated means. I found out.","mono":false,"off":94.0953,"dur":2.795,"env":"027997678754400877658610226775434214875664566777654323342002677215866656543210110000"},"ep10_026":{"who":"RIN","text":"Where?","mono":false,"off":97.29,"dur":0.555,"env":"06999876653110000"},"ep10_027":{"who":"HARUKI","text":"Down here. Under the cathedral. There are forty beds of crystal. Forty people asleep in them. Their Brands are gone.","mono":false,"off":98.2447,"dur":5.632,"env":"0499776777867742576674651286101777434532210003898630038775665266654444101277543025432101687666411176402655555424775126554211110000000000388642887776654653267654321100000"},"ep10_028":{"who":"HARUKI","text":"Not grey. Gone. Like someone scraped the light out of them with a spoon.","mono":false,"off":104.2767,"dur":3.243,"env":"03898622168877676432877776433310027754438666654410787302655766645665543666552344430057653212000000"},"ep10_029":{"who":"RIN","text":"Are they alive?","mono":false,"off":107.9193,"dur":0.981,"env":"058729998877866554442011100000"},"ep10_030":{"who":"HARUKI","text":"They breathe. That is all. I knew one of them. Mira, from Osaka. She taught me how to buy bread here. She was consecrated last spring.","mono":false,"off":109.3007,"dur":6.656,"env":"04997427877763000276647654566766520257787776566554212110000000003799877675312774137765434765301276543222344237851356755565553555653158764422432100000013386753023766344311775563245665443330036532100000"},"ep10_031":{"who":"HARUKI","text":"Lucien told me she went home.","mono":false,"off":116.3567,"dur":1.877,"env":"046997743286652339876356653325656774245877643212121000000"},"ep10_032":{"who":"RIN","text":"...I am sorry, Haruki.","mono":false,"off":118.634,"dur":1.515,"env":"0267999995553988898632257767750111543210000000"},"ep10_033":{"who":"HARUKI","text":"Don't be sorry. Takuto says you say that. Be useful.","mono":false,"off":120.5487,"dur":2.901,"env":"0697425643227676666543114774116742275543236543553215655535544200005654566533101221100000"},"ep10_034":{"who":"RIN","text":"He told you that?","mono":false,"off":123.85,"dur":1.088,"env":"027513489996236753754432101100000"},"ep10_035":{"who":"HARUKI","text":"He tells me everything you say. He pretends he doesn't. He is a bad liar.","mono":false,"off":125.338,"dur":3.861,"env":"00773449777426863158634774055666653332666543310004731762349656425644776435321100000577755742777773355777654322110000"},"ep10_036":{"who":"RIN","text":"What will you do?","mono":false,"off":129.5993,"dur":0.917,"env":"0594386566623576433210000000"},"ep10_037":{"who":"HARUKI","text":"I do not know yet. But I am not sitting in a golden chair. Ever.","mono":false,"off":130.9167,"dur":3.349,"env":"17967888852587777668764100067687776677775235445857767665327766545665343376543221000000687334311100000"},"ep10_038":{"who":"SIEG","text":"Stay here, Takuto. With Haruki. You came all this way for him.","mono":false,"off":134.666,"dur":4.48,"env":"024139766777866555301387653017875226766554300000000696234866667665201476543200000000039722987773015665555665422765565213644454322110000"},"ep10_039":{"who":"TAKUTO","text":"No.","mono":false,"off":139.546,"dur":0.619,"env":"0145899876432000000"},"ep10_040":{"who":"SIEG","text":"You keep saying no to powerful people. It is a bad habit.","mono":false,"off":140.5647,"dur":3.691,"env":"099423985213437776666777765666655225511576666641166410397510654410000000000799986876416655564543676532321021000"},"ep10_041":{"who":"TAKUTO","text":"You are not a powerful person. You are Sieg.","mono":false,"off":144.6553,"dur":2.56,"env":"01367998677877303566774114411157753322211100000025565534433454321100000000000"},"ep10_042":{"who":"SIEG","text":"Ha. That might be the nicest thing you have ever said to me.","mono":false,"off":147.6153,"dur":3.115,"env":"0198776653000587400278752129767677765565324653101777776667753000575575332387642126555433210000"},"ep10_043":{"who":"SIEG","text":"Morvudd took eleven from me. If it takes you, I will not be able to count anymore. Do you understand?","mono":false,"off":151.13,"dur":6.037,"env":"09876656653301467300667666644665411665555444420000000000396284103297632343287766300000006777767765520066665465235112775564376666666654333100000000000188877666466443107776544222110000"},"ep10_044":{"who":"TAKUTO","text":"If it takes you, I will have to start counting. I do not want to learn.","mono":false,"off":157.5673,"dur":4.053,"env":"05216500427993034323444424555454334563101234215543001145444302221100000000000003552565666423455444433455432110000000000000"},"ep10_045":{"who":"SIEG","text":"...Stubborn.","mono":false,"off":162.0207,"dur":0.939,"env":"04753204987678776565553210000"},"ep10_046":{"who":"TAKUTO","text":"You taught me. Always the first move.","mono":false,"off":163.3593,"dur":2.155,"env":"01312248984023333100005666435543203211034332300334321100000000000"},"ep10_047":{"who":"SIEG","text":"I taught you that for fighting, not for arguing with me.","mono":false,"off":165.914,"dur":3.221,"env":"0686234397642236865665211157511175556566554310000000078653111740056655545765555555641145432210000"},"ep10_048":{"who":"TAKUTO","text":"It works for both.","mono":false,"off":169.5353,"dur":1.173,"env":"046534998315411663269874211000000000"},"ep10_049":{"who":"HUNTER","text":"Make way! Guild wagon from Ashford! Make way!","mono":false,"off":171.1087,"dur":3.243,"env":"02553002689876531015654222467752243310132201344422210022221001222000124322211100000000000000000000"},"ep10_050":{"who":"VALENTINE","text":"Darlings! We heard there was a Calamity. We simply could not miss it.","mono":false,"off":174.7513,"dur":3.541,"env":"04899986555444422102431246675103543323301134444444322221000000155334464003510142155445203543321221011000000"},"ep10_051":{"who":"SIEG","text":"Valentine. Gideon. You came all the way from Ashford?","mono":false,"off":178.6927,"dur":3.669,"env":"059665666654287666666664000000198678765444430000000004972289767730036665556656656651177520456544421464322110000"},"ep10_052":{"who":"GIDEON","text":"Twelve days in a wagon with Tofu. He sings. Did you know he sings? Nobody warned me he sings.","mono":false,"off":182.762,"dur":6.144,"env":"01299862101676532221113334432357653012222122000124541000110000000000023332246532211010000000000000032258688874233211235532221010000000000000257883144143323566532222212111223321100010000"},"ep10_053":{"who":"VALENTINE","text":"He sings beautifully.","mono":false,"off":189.306,"dur":1.685,"env":"004775343398788862100356799583001533322210000000000"},"ep10_054":{"who":"GIDEON","text":"He sings in error codes!","mono":false,"off":191.3913,"dur":1.749,"env":"02643332898433321100003442014785432100125432110011000"},"ep10_055":{"who":"GIDEON","text":"Boy. Arms out. I rewound your harness on the road. Double chains. Two blocks a day now.","mono":false,"off":193.5407,"dur":5.952,"env":"07899864332025655445332553211000000000000000268579736788876244211577543222224554543366642211000000000000003995124310133355432111011100000000225563026764320023232144333222211000000"},"ep10_056":{"who":"TAKUTO","text":"Two?","mono":false,"off":199.8927,"dur":0.555,"env":"14699976442210000"},"ep10_057":{"who":"GIDEON","text":"Two. Spend the first one on yourself, for once. I insist. The second one, I know you will waste on somebody old.","mono":false,"off":200.8473,"dur":6.869,"env":"013787532100000010496652111687430015555444431222453200000232233211110000000000025544333111112541001000000000000000000333349721343232221000000136568886334324432235543111101334321112554432342123344532111000000"},"ep10_058":{"who":"TAKUTO","text":"...Thank you, Gideon.","mono":false,"off":208.1167,"dur":1.216,"env":"0011598650114542138854433221110000000"},"ep10_059":{"who":"NEMU","text":"Tofu. You came too.","mono":false,"off":209.7327,"dur":1.451,"env":"03289942213442100540324877541451576310000000"},"ep10_060":{"who":"VALENTINE","text":"He wanted to see Takuto. He has been practising reading errors all the way here.","mono":false,"off":211.5833,"dur":4.48,"env":"015448974233012333324331021355200033203023222210000000000025446963105554012650002233344333554154322333333222004554413423444310122111000"},"ep10_061":{"who":"WICK","text":"Gideon! Takoyaki and Takoyaki say hello! Look, I only burn what I look at now!","mono":false,"off":216.4633,"dur":4.523,"env":"0299466776665152860159878788511156663456201676666620144654655326645665322100000017721105664467777522876665563654455114223322211100000000"},"ep10_062":{"who":"GIDEON","text":"Then stop looking at my hat.","mono":false,"off":221.386,"dur":1.771,"env":"015897744320897531000003982223343312333211244210000000"},"ep10_063":{"who":"VALENTINE","text":"Sieg. You look like a man walking to his own funeral.","mono":false,"off":223.5567,"dur":3.029,"env":"0235566664101000036659600166214566666655535861013442313444446555530012566543222110000000000"},"ep10_064":{"who":"SIEG","text":"I am walking to Morvudd's. I would like you there.","mono":false,"off":226.986,"dur":2.88,"env":"188876677777621167775349987666656755443443100000000599997568776531014987477654432210000"},"ep10_065":{"who":"VALENTINE","text":"...Then I will bring a very good dress. And my Encore.","mono":false,"off":230.266,"dur":2.965,"env":"00289987558858711766662187667401674100446653212455310000589987765368888502133222100000000"},"ep10_066":{"who":"VESPER","text":"And I will bring my letter.","mono":false,"off":233.6313,"dur":1.792,"env":"001789430556652366210057655555554444345543222111210000"},"ep10_067":{"who":"TAKUTO","text":"Vesper.","mono":false,"off":235.8233,"dur":0.747,"env":"00179854200776431100000"},"ep10_068":{"who":"VESPER","text":"The Guild sent me to watch you on the plains, error. If the axe goes red near a city of a hundred thousand people, I do my job.","mono":false,"off":236.97,"dur":7.232,"env":"0421798520221763125522143255541022143224555200045444333332111000244433222210000000000002610153036553011201665212257541045443332222115523332132142111567624520004544432244200232002322100003452136454343112454332222100000"},"ep10_069":{"who":"TAKUTO","text":"Then watch.","mono":false,"off":244.602,"dur":0.939,"env":"00188866668998642102321000000"},"ep10_070":{"who":"VESPER","text":"...I intend to.","mono":false,"off":245.9407,"dur":1.365,"env":"00125999987984232598997303346544443321000"},"ep10_071":{"who":"CROWD","text":"Keep moving! The Hunters are holding the bridge! Keep moving!","mono":false,"off":247.706,"dur":3.52,"env":"0026510279999524433220142138862335433345421015655245554301466532110122100000000430025544201111000000000000"},"ep10_072":{"who":"CROWD2","text":"Mama, are the monsters coming?","mono":false,"off":251.626,"dur":1.984,"env":"025999986666665425762533466653221354331114533432211000000000"},"ep10_073":{"who":"CROWD","text":"Thank you, Hunters! Gods keep you!","mono":false,"off":254.01,"dur":2.24,"env":"00699970058874379872144322122100178987523400045400133221110000000000"},"ep10_074":{"who":"CROWD2","text":"Bye, Mister Hunters!","mono":false,"off":256.65,"dur":1.6,"env":"019988877654445311155324643222443322111100000000"},"ep10_075":{"who":"WICK","text":"There are so many of them. Carts and cows and grandmas. They are never going to make it in time.","mono":false,"off":258.65,"dur":4.928,"env":"0787874444498767676566674105444320011298862043245302226666555543334431156565554432211232000000057766777843752166652346541153444313145432111000000000"},"ep10_076":{"who":"NEMU","text":"They will, if we stand here long enough.","mono":false,"off":263.978,"dur":2.368,"env":"002453104998521000000000000531175541588875311455533555554432221100110000"},"ep10_077":{"who":"WICK","text":"How long is long enough?","mono":false,"off":266.746,"dur":1.28,"env":"006998679887778653787666665422100000000"},"ep10_078":{"who":"NEMU","text":"Until we cannot stand.","mono":false,"off":268.426,"dur":1.493,"env":"039725169855820326657643002340567542110002000"},"ep10_079":{"who":"WICK","text":"...I hate that answer. It is the right answer. I hate it.","mono":false,"off":270.3193,"dur":2.624,"env":"0767659940199433676634355542004656416648975135565333343214544215544132100000000"},"ep10_080":{"who":"WICK","text":"Grandma! Grandma, I will carry you! I am rank F, I am very strong!","mono":false,"off":273.3433,"dur":3.541,"env":"03988888899863117988877787753685640226987654443221000036887878877326773116566762387654674137543211100000000"},"ep10_081":{"who":"CROWD2","text":"Your head is on fire, young man.","mono":false,"off":277.2847,"dur":2.091,"env":"013998433796573366542100297775444432146533333433322111000000000"},"ep10_082":{"who":"CROWD2","text":"It is very warm. Carry on.","mono":false,"off":279.7753,"dur":1.984,"env":"069597332167666542245555543221101138875445554432110000000000"},"ep10_083":{"who":"NEMU","text":"Children. This way. Hold the tail. Everybody hold the tail. Do not let go.","mono":false,"off":282.1593,"dur":5.76,"env":"03427652225654431156334202211100000000000000000000000000198662035042143321100000000000000000000029811684056552541115655401413314332211000000025678754200364200035543211000000"},"ep10_084":{"who":"GIDEON","text":"Valentine, the bridge rails. Iron. If I wake them, they will hold for an hour.","mono":false,"off":288.3193,"dur":5.355,"env":"00299895776513145653223221442047751121155432111121000000000000367654332210000000000000000034368997389840100343321000004664652111279754311111566544213343321100000"},"ep10_085":{"who":"VALENTINE","text":"And I will put on a show for the front row. Sieg, darling, how long do you need?","mono":false,"off":294.074,"dur":3.947,"env":"06659985940135466654655577764111413201454201344333220000000000145667741100688765444332124776667777664222444443322111000"},"ep10_086":{"who":"SIEG","text":"Until the last cart is over the hill.","mono":false,"off":298.4207,"dur":2.496,"env":"279647976676776655553210128766665121000000598544776576557752397753333221000"},"ep10_087":{"who":"VALENTINE","text":"Then it will be a long show. I adore long shows.","mono":false,"off":301.3167,"dur":2.837,"env":"03776227405776678998873442443322210000000466677227766744566755533444543322212320000000"},"ep10_088":{"who":"RIN","text":"Sieg. The bridge is narrow. Twenty paces. They can only come at us five at a time.","mono":false,"off":304.554,"dur":4.544,"env":"01234667662010083018998313464326665555555442000115664530136652222432122100000005416644777776111256555444523310455444143430213433222210000"},"ep10_089":{"who":"SIEG","text":"Good eye. Five at a time is a conversation. Five hundred at a time is a funeral.","mono":false,"off":309.498,"dur":5.589,"env":"079666544444555300000565555564102556520227645555553000265641148655454322666543324321000000000000017655643247555456542002666620223755555555200000555741015776443322110000"},"ep10_090":{"who":"RIN","text":"And Morvudd?","mono":false,"off":315.4873,"dur":0.917,"env":"0579999999985267544122100000"},"ep10_091":{"who":"SIEG","text":"Morvudd does not use bridges. Morvudd is what the river is afraid of.","mono":false,"off":316.8047,"dur":4.736,"env":"07977654655331366543876554100377766430007765433443323321000000000069876665565543200000067667751005666677544655410047546521115766664443221100000"},"ep10_092":{"who":"WICK","text":"Sieg. You promised. At Grey Hollow, your squad asked for the one about the bear and the bishop. Tell it. Please.","mono":false,"off":321.9407,"dur":5.589,"env":"024387774346862127888666644301037421279888754799876665545534301787777542366664420115647556666476304431776666555665217743343200000000000031887552001136543211233200000000"},"ep10_093":{"who":"SIEG","text":"You want the bear and the bishop? Tonight?","mono":false,"off":327.93,"dur":2.517,"env":"0787666531146643565555555421257765426654335631000000000239887766553212210000"},"ep10_094":{"who":"NEMU","text":"Tonight is the best night for it. Tomorrow we might be dead and never hear the ending.","mono":false,"off":330.8473,"dur":6.464,"env":"03167877753002000765402510165532434004655410211131211000200000000000000000000000000326999788876543321000000068778763102341056543211111000000000000000000387668841354111466540441028865432110000000"},"ep10_095":{"who":"RIN","text":"Nemu!","mono":false,"off":337.7113,"dur":0.768,"env":"047899999988654211100000"},"ep10_096":{"who":"NEMU","text":"It is true!","mono":false,"off":338.8793,"dur":0.896,"env":"069727634303215885321000000"},"ep10_097":{"who":"SIEG","text":"...Ha. Fine. A bear walks into a cathedral, and asks the bishop for a blessing.","mono":false,"off":340.1753,"dur":4.565,"env":"02786553111177655667654420000000018965866566776542234775576413961048775466655200000027833666542142077548654375100158765347765432443211000"},"ep10_098":{"who":"SIEG","text":"The bishop says, my son, the church does not bless bears. The bear says, that is fine, I will wait.","mono":false,"off":345.1407,"dur":6.187,"env":"069789654574123277766653100006768633277666553100065152977531230177679765210277653200067776543322210000000000002985976666533277666542000058769753100776666666652002688766666556554220010000"},"ep10_099":{"who":"SIEG","text":"Forty years later, the bishop is dying. And the bear is still there. Still waiting.","mono":false,"off":351.7273,"dur":4.971,"env":"005876565555655543476555466554100004763865436520366520077555565443320000000000698864475555434543220276555576665433200000001330497776676655344322100000"},"ep10_100":{"who":"SIEG","text":"So the bishop sighs, and blesses the bear. And the bear says, thank you. Now I can eat you. I have been very hungry.","mono":false,"off":357.098,"dur":6.955,"env":"02497776486453652133267655556655310005875287653325664107542776544332100000000000069986557655543326666655431000087763113865410000004987665456631497300575312256432000000000048997448776557655666448666424432210000"},"ep10_101":{"who":"WICK","text":"...That is a terrible joke.","mono":false,"off":364.4527,"dur":1.408,"env":"0399779558324588786446642236865431001000000"},"ep10_102":{"who":"SIEG","text":"Yes. Mara used to say so every time. Then she would laugh until she cried.","mono":false,"off":366.2607,"dur":4.885,"env":"299765523321038875555566555665301563248766433873003664476522176555544332100000000000787776443766754676655553000000068624865432652024865443322100000"},"ep10_103":{"who":"NEMU","text":"Ha. Ha ha. Patience is a very scary bear.","mono":false,"off":371.546,"dur":3.435,"env":"00199761013997214532110000000000000000000033397564525542122200974753118876665342303554444305532111100000"},"ep10_104":{"who":"RIN","text":"Ha... that is so stupid. Why am I laughing?","mono":false,"off":375.3807,"dur":2.475,"env":"007999963198848554597444238840167612000037989988877776776652113433210000000"},"ep10_105":{"who":"TAKUTO","text":"Because it is stupid.","mono":false,"off":378.2553,"dur":1.216,"env":"0033139636556322200555301321100000000"},"ep10_106":{"who":"SIEG","text":"That is the whole secret of it. You laugh because tomorrow does not care. Thank you. All of you. I have not told it in six years.","mono":false,"off":379.8713,"dur":7.659,"env":"07752676522775278656653332474201663564443110000000000007988766555310006517975113887655555666553676546875553000117766654431000000003987620178764100002777777546665553000000000004899757875410227766657636666432265123258755332212322000"},"ep10_107":{"who":"KUROZANE","text":"A bear and a bishop. You still tell it wrong, Valen.","mono":false,"off":387.93,"dur":3.307,"env":"0143205999877655532036523223321000000023222016653011355443112344443332102433321111111000000000000000"},"ep10_108":{"who":"WICK","text":"The WOLF! Swords! Everybody, swords!","mono":false,"off":391.6367,"dur":1.877,"env":"265699931233788888523238437853988555433255443321121000000"},"ep10_109":{"who":"KUROZANE","text":"Sheathe them. I did not come for you.","mono":false,"off":393.914,"dur":2.475,"env":"012346999621116876553116762474357898410021564420034333333221110000000000000"},"ep10_110":{"who":"SIEG","text":"Then why?","mono":false,"off":396.7887,"dur":0.96,"env":"05997878887766776666553100000"},"ep10_111":{"who":"KUROZANE","text":"Morvudd ate my pack's mother when I was a pup. Sable fed her to it, to make me hungry. I only learned that last week.","mono":false,"off":398.1487,"dur":7.424,"env":"0245679932896322565310244442002235542012124442233222222223222122000014420000000000000012257752353110067651343102123321001133332000322112333311222111000000000234344444443344443322343101233443212100122100000000000000000000000"},"ep10_112":{"who":"KUROZANE","text":"I have my own debts on that bridge tomorrow.","mono":false,"off":405.9727,"dur":3.072,"env":"004655697126876643466555312876420012110233333330000145531121021333333333221110000000000000000"},"ep10_113":{"who":"SIEG","text":"And after?","mono":false,"off":409.4447,"dur":0.939,"env":"06896425665652128866555310000"},"ep10_114":{"who":"KUROZANE","text":"After, we finish our duel. If either of us is still standing.","mono":false,"off":410.7833,"dur":3.904,"env":"0369993000797465200665542246542104654433221100003300004674577652255311112111101443211100433333322111110000000000000000"},"ep10_115":{"who":"SIEG","text":"...After, then.","mono":false,"off":415.0873,"dur":1.131,"env":"0388762128998887779778665555420000"},"ep10_116":{"who":"RIN","text":"Give me your wrist.","mono":false,"off":416.618,"dur":1.067,"env":"02796248776665347652112211200000"},"ep10_117":{"who":"TAKUTO","text":"The thread?","mono":false,"off":418.0847,"dur":0.811,"env":"0045211248988643110000000"},"ep10_118":{"who":"RIN","text":"No. This. A strip of the scarf. Kaito's scarf. I cut it last night.","mono":false,"off":419.2953,"dur":3.797,"env":"037899999842998322126333128810532533304766543200000115788678753330166654431001355101265562245443221333221000000000"},"ep10_119":{"who":"TAKUTO","text":"Rin. You said it stays the way he wore it.","mono":false,"off":423.4927,"dur":2.475,"env":"013788865431000134343894521430475553203433544431133223467663311100000000000"},"ep10_120":{"who":"RIN","text":"He would have wanted a piece of it on the bridge. He liked bridges. He liked last stands. He was a show-off.","mono":false,"off":426.3673,"dur":5.717,"env":"0265979434777752444600145523252575313566652046765431112210000058688871011004886212354432310057567764001245676423333044443333322200000000005556345333256556443221000000000000"},"ep10_121":{"who":"RIN","text":"If the thread snaps tomorrow, the scarf still holds. Then you still have something to pull on.","mono":false,"off":432.4847,"dur":5.035,"env":"07600087101369883143267653012125776666666656522533215776511222157653136765333102210000000015988887533227875334662132544114441220004555444332221000000000"},"ep10_122":{"who":"TAKUTO","text":"...I will give it back.","mono":false,"off":437.9193,"dur":1.152,"env":"00047887732993752177753210000000000"},"ep10_123":{"who":"RIN","text":"You had better. With you still attached.","mono":false,"off":439.4713,"dur":1.899,"env":"047557954119987787653463046434048777402254432101221000000"},"ep10_124":{"who":"KUROZANE","text":"You did not sleep.","mono":false,"off":441.77,"dur":1.557,"env":"00245633993467888740011112334332210000000000000"},"ep10_125":{"who":"SIEG","text":"Neither did you.","mono":false,"off":443.7273,"dur":1.237,"env":"07987756776665369765567877544442100000"},"ep10_126":{"who":"KUROZANE","text":"Wolves do not sleep before a hunt. We listen to the ground.","mono":false,"off":445.3647,"dur":3.904,"env":"0023699998422201565567741012212444310002310034544321124432100000000013433475111332012121034433222111110000000000000000"},"ep10_127":{"who":"SIEG","text":"And what does the ground say?","mono":false,"off":449.6687,"dur":1.6,"env":"058998640017665415754487655566633217764433321000"},"ep10_128":{"who":"KUROZANE","text":"That something very heavy is walking toward us, and that it is hungry, and that it remembers you.","mono":false,"off":451.6687,"dur":5.675,"env":"005981033885205655216887654212464134323311125651002321111234554233211111100002343444232123111111454442133222110000001233344334100133333333322221111011100000000000000000000"},"ep10_129":{"who":"SIEG","text":"It should. I put a scar on it too, six years ago. Right before it put eleven on me.","mono":false,"off":457.7433,"dur":4.992,"env":"085454479876554200002783195764401765566666674100131977666523325621322887754643565433200000000003986310386215777521019648776766457665455555554432210000"},"ep10_130":{"who":"KUROZANE","text":"Then today we give it more scars than it can count.","mono":false,"off":463.1353,"dur":3.285,"env":"012887741443998876543343115625612444442222201578776533321100222100023210111333211000000000000000000"},"ep10_131":{"who":"SIEG","text":"Careful, Kurozane. You almost sound like a friend.","mono":false,"off":466.8207,"dur":3.115,"env":"0299765115666541012297666655776555443200000000896566665664333276555656552174110577654332210000"},"ep10_132":{"who":"KUROZANE","text":"Do not insult me before breakfast, Valen.","mono":false,"off":470.3353,"dur":2.987,"env":"001576789995002555422387631244324200045532136640000232111000113444322221111100000000000000"},"ep10_133":{"who":"NEMU","text":"Two lives, Takuto.","mono":false,"off":473.722,"dur":1.557,"env":"03269856666554331033210000356501153031311100000"},"ep10_134":{"who":"TAKUTO","text":"I know.","mono":false,"off":475.6793,"dur":0.747,"env":"03677778999854210000000"},"ep10_135":{"who":"NEMU","text":"If I use one today, do not be sad. It is what they are for. They are not for keeping in a jar.","mono":false,"off":476.826,"dur":7.488,"env":"021134698852588754410677644231565432210000000000004698997541002333433343211100010000000000000000000000000000393775410146530005665445541111332211100000000000000000000125678877679865301111220022156005654454551352543322111100000"},"ep10_136":{"who":"TAKUTO","text":"You are not using one today.","mono":false,"off":484.714,"dur":1.749,"env":"00257866799961024543444444455442333226532100000000000"},"ep10_137":{"who":"NEMU","text":"Mm. I will try very hard. I am lazy. Dying is a lot of work.","mono":false,"off":486.8633,"dur":5.312,"env":"0246667765444200000000259623043145662016544541111453321000110000003777544455432233311000000000000000000000000000000466567654443220055342233343311004421000010000"},"ep10_138":{"who":"TAKUTO","text":"...Stay near Wick. He is warm.","mono":false,"off":492.5753,"dur":1.749,"env":"00330796766666633985001002454332235666542110000000000"},"ep10_139":{"who":"NEMU","text":"He is very warm. Okay.","mono":false,"off":494.7247,"dur":2.048,"env":"00067645116656653145555543211000000000000029972023133211000000"},"ep10_140":{"who":"RIN","text":"Here they come. The whole horizon is moving.","mono":false,"off":497.1727,"dur":2.368,"env":"006998188401157665430000531158777312664776656443444313332555521321100000"},"ep10_141":{"who":"SIEG","text":"Five at a time. Remember. Five at a time.","mono":false,"off":499.9407,"dur":3.221,"env":"0048555567534566741342765566655531000003999875655565540000000148655667534565641343975544432210000"},"ep10_142":{"who":"SIEG","text":"Afterimage! First five!","mono":false,"off":503.562,"dur":1.856,"env":"06876302998788776665310000019977741210786666555432100000"},"ep10_143":{"who":"TAKUTO","text":"Break!","mono":false,"off":505.818,"dur":0.64,"env":"00489976520011100000"},"ep10_144":{"who":"KUROZANE","text":"Fang Draw!","mono":false,"off":506.858,"dur":1.28,"env":"000197777677752135787765332111000000000"},"ep10_145":{"who":"RIN","text":"Red Thread, tie the front ones to the river!","mono":false,"off":508.538,"dur":2.261,"env":"03899620013798896221022466784541117752255665433344645872143211000000"},"ep10_146":{"who":"WICK","text":"Fire head! Only Fiends! Only... there are SO MANY Fiends!","mono":false,"off":511.1993,"dur":3.008,"env":"0098656753467623356556510026555453311455555433220000455533335655545430003443211112220000000"},"ep10_147":{"who":"WICK","text":"Will-o'-Wisp! The whole front row!","mono":false,"off":514.6073,"dur":1.707,"env":"0597899897688755100474267762113875224565432211000000"},"ep10_148":{"who":"NEMU","text":"They are climbing the rails!","mono":false,"off":516.714,"dur":1.429,"env":"0136664002300679986665454155432110000333200"},"ep10_149":{"who":"HARUKI","text":"Frozen Hour!","mono":false,"off":518.5433,"dur":1.237,"env":"01117986767558665566666554433333100000"},"ep10_150":{"who":"TAKUTO","text":"Haruki?!","mono":false,"off":520.1807,"dur":0.981,"env":"000479878740115653211011000000"},"ep10_151":{"who":"HARUKI","text":"Lucien said stay. I have stayed for two years. Today I am not staying.","mono":false,"off":521.562,"dur":3.669,"env":"036977532666532387433210676544310005777332026565311552031665546554322210146477665565554556641221065543211100000"},"ep10_152":{"who":"TAKUTO","text":"...About time.","mono":false,"off":525.6313,"dur":0.981,"env":"015429987204356655321110000000"},"ep10_153":{"who":"HARUKI","text":"Three seconds! Go!","mono":false,"off":527.0127,"dur":1.536,"env":"00037987775434995137666544337887764433333100000"},"ep10_154":{"who":"TAKUTO","text":"Break, break, break!","mono":false,"off":528.9487,"dur":1.131,"env":"0047872005976211257754210011000000"},"ep10_155":{"who":"VALENTINE","text":"Encore! Ladies and gentlemen, the front row!","mono":false,"off":530.4793,"dur":2.709,"env":"0799774212655420013557641444344345404466543133333221120004542010245432211000000000"},"ep10_156":{"who":"VALENTINE","text":"Again! And again! You will dance this step forever, darlings!","mono":false,"off":533.5887,"dur":3.328,"env":"0440498877852246540366654442000000464793059776314303523440244100004666304420456543322222112200000000"},"ep10_157":{"who":"GIDEON","text":"Cogwheel Core! Every rail on this bridge, wake up and HOLD!","mono":false,"off":537.3167,"dur":3.712,"env":"0137887311454310113532100000000000000016942366643487754323433322200024432210111001444112431002321136632111000000"},"ep10_158":{"who":"GIDEON","text":"Chains! Bind them to the stones!","mono":false,"off":541.4287,"dur":1.963,"env":"01359986432211100000288776654444312223222200576432111001000"},"ep10_159":{"who":"VESPER","text":"White Gale. The flank is mine.","mono":false,"off":543.7913,"dur":2.048,"env":"02489984000049788766544200531114886640144435776554333333210000"},"ep10_160":{"who":"SIEG","text":"There. Behind them.","mono":false,"off":546.2393,"dur":1.344,"env":"06986666654320776367666777646544443210000"},"ep10_161":{"who":"KUROZANE","text":"Morvudd.","mono":false,"off":547.9833,"dur":0.981,"env":"002467889999722654332100000000"},"ep10_162":{"who":"SIEG","text":"Hello again. You got bigger.","mono":false,"off":549.3647,"dur":1.941,"env":"01798776565655466666555530000028864765521007763454332210000"},"ep10_163":{"who":"SIEG","text":"Everyone off the bridge. All of you. Get to the villagers. That is an order.","mono":false,"off":551.706,"dur":4.715,"env":"0586577666665543466511027631587666643334310000007777776567776665400000008521387787686667653446544434310000000068835976688740058887643432210000"},"ep10_164":{"who":"TAKUTO","text":"Sieg!","mono":false,"off":556.8207,"dur":0.704,"env":"0122699985237752100000"},"ep10_165":{"who":"SIEG","text":"Five at a time, Takuto. This one is my five. GO!","mono":false,"off":557.9247,"dur":3.925,"env":"0059666674456675323875556666654102296630198522876555300000078641486566665487555662106655544443100000000089875433210000"},"ep10_166":{"who":"SIEG","text":"Mara! Joss!","mono":false,"off":562.25,"dur":1.28,"env":"099766677766663134569976665543222100000"},"ep10_167":{"who":"SIEG","text":"Pell! Bram! Bren!","mono":false,"off":563.93,"dur":1.451,"env":"02976556653776555566653100088776644433100000"},"ep10_168":{"who":"SIEG","text":"...Hask. Tova.","mono":false,"off":565.7807,"dur":1.323,"env":"0279876664420177641379778976665443210000"},"ep10_169":{"who":"SIEG","text":"Corin! Dace!","mono":false,"off":567.5033,"dur":1.237,"env":"03986666655555543247666654322222100000"},"ep10_170":{"who":"SIEG","text":"Ilse. Wen.","mono":false,"off":569.1407,"dur":1.109,"env":"0698777775332189987777655553200000"},"ep10_171":{"who":"SIEG","text":"...Twelve. Nemu. Thirteen. Wick.","mono":false,"off":570.65,"dur":2.24,"env":"04369866656655577765567766655411117877523787665530000589752000110000"},"ep10_172":{"who":"SIEG","text":"Fourteen. Rin. Fifteen... Takuto.","mono":false,"off":573.29,"dur":2.688,"env":"003976642377666666676555555420000286410177766655200000039863139763358654322210000"},"ep10_173":{"who":"TAKUTO","text":"Sieg is on the bridge alone. I have to...","mono":false,"off":576.378,"dur":2.496,"env":"012327752296469866742169962347446777532110000055534577711023332110000000000"},"ep10_174":{"who":"TAKUTO","text":"Why is everything stopped? The rain is stopped.","mono":false,"off":579.274,"dur":2.688,"env":"002699999984456943662055534307988532100000000375488787767545420777421000000000000"},"ep10_175":{"who":"SABLE","text":"Hello, Takuto. Finally. I have so wanted to say hello properly.","mono":false,"off":582.362,"dur":4.885,"env":"001138789986543112323321012212422222221000002343344222121110000000002223336753533333111236763323211223333210012221011111210000000000000000000000000"},"ep10_176":{"who":"TAKUTO","text":"Sable.","mono":false,"off":587.6473,"dur":0.725,"env":"0023799973786532100000"},"ep10_177":{"who":"SABLE","text":"Mister Sable, please. We are going to be close, you and I. Closer than you know.","mono":false,"off":588.7727,"dur":4.885,"env":"000169693234765553212220012444322221232100000133452245432211121011244321233211233333234433211100000113433432213444344422211100000000000000000000000"},"ep10_178":{"who":"TAKUTO","text":"What did you do to the rain?","mono":false,"off":594.058,"dur":1.536,"env":"01495025223454212655222244336555321100000000000"},"ep10_179":{"who":"SABLE","text":"Nothing. I simply stepped between two seconds. It is very quiet here. A good place to talk.","mono":false,"off":595.994,"dur":6.08,"env":"000469961034544211333554531132334324321000111124332232232244433200011221121100000013234221145544311113443222100112111100000000001212552101234322321111111222210000000000000000000000000"},"ep10_180":{"who":"SABLE","text":"I want you to know something before your teacher dies. I am the one who brought you here.","mono":false,"off":602.474,"dur":4.907,"env":"0000498579633332474554489753221023442122123333212321212422213332322223543100000000145566776554443444434321234531222210122121100000000000000000000000"},"ep10_181":{"who":"SABLE","text":"The crossing. Two fourteen in the morning. The cat. I opened that Rift. I chose you.","mono":false,"off":607.7807,"dur":5.397,"env":"000151233575699653431354432113633133233444433442323332222110000121111246543101211000000245666323534554211234421000001012321364233332321121110000000000000000000000"},"ep10_182":{"who":"TAKUTO","text":"Why me?","mono":false,"off":613.578,"dur":0.811,"env":"0027998775665432100000000"},"ep10_183":{"who":"SABLE","text":"Because a key needs a hand. The thing in your axe is sealed with a lock that only Ruinbreaker can open. And Ruinbreaker only wakes in someone who would break the world to save one person.","mono":false,"off":614.7887,"dur":10.304,"env":""},"ep10_184":{"who":"TAKUTO","text":"Haruki.","mono":false,"off":625.4927,"dur":0.939,"env":"00148997874021455321110000000"},"ep10_185":{"who":"SABLE","text":"Bait. Very sweet bait. I took him first, two years ago, so that you would come looking. And you came. Everyone always comes.","mono":false,"off":626.8313,"dur":7.509,"env":"0004986410001367654467521221000123222100110000000000002213452115441125433343102323344432322112222113422121112212210112223322310001111100000000233321111133221110000000001343123433322333332224211122121111232100000000000000000000"},"ep10_186":{"who":"AKURO","text":"Boy. BOY. Let me out. Let me at him. I have waited three hundred years to put my hands on that grin.","mono":true,"off":634.7407,"dur":7.424,"env":"0123877798685745210168878876866532113576413577677754311111236853245666541135442211000000000000357764246532458776456410111234543233256764367631223346666333233222201358223455442111345655444434444333432100113444332111112210000"},"ep10_187":{"who":"TAKUTO","text":"Not yet.","mono":false,"off":642.5647,"dur":0.811,"env":"0135675223797531001100000"},"ep10_188":{"who":"SABLE","text":"Not yet? Oh, I love that. Not yet. That is what everyone says, right before.","mono":false,"off":643.7753,"dur":5.397,"env":"000479972136765211210134565223333335420013322110100001344331122443210122100000000345322353233212331223223445985322223311333210011002222211100000000000000000000000"},"ep10_189":{"who":"SABLE","text":"Go on. Your teacher is counting. He is nearly at fifteen.","mono":false,"off":649.5727,"dur":4.053,"env":"00002796455546543322122114323113322224421123322322211111000000012324444433312222200001310000122221000000000000000000000000"},"ep10_190":{"who":"TAKUTO","text":"Get away from him.","mono":false,"off":654.026,"dur":1.173,"env":"038687459887422154433553211000000000"},"ep10_191":{"who":"AKURO","text":"Yes. YES. Open it. All the way this time. He killed your teacher. He took your friend.","mono":true,"off":655.5993,"dur":6.059,"env":"01345978665433212458965543332101578684126776554420000147788699547774357878735654332122466555333322100024311113479976334642122144331333433321100014421224641002565211114665433321110000"},"ep10_192":{"who":"TAKUTO","text":"He... he...","mono":false,"off":662.058,"dur":0.939,"env":"00069988524169986432111000000"},"ep10_193":{"who":"HARUKI","text":"Takuto.","mono":false,"off":663.3967,"dur":1.045,"env":"01239877522876435866544433100000"},"ep10_194":{"who":"HARUKI","text":"That is enough. They get it.","mono":false,"off":664.842,"dur":1.664,"env":"02698757755877777776300137775535877544310221000000"},"ep10_195":{"who":"TAKUTO","text":"...Haruki.","mono":false,"off":666.906,"dur":1.024,"env":"0011589867874102134432101000000"},"ep10_196":{"who":"HARUKI","text":"You put my hand there. Remember? If I was wrong about him, I would do it again.","mono":false,"off":668.33,"dur":3.968,"env":"018722952676762286667657665542005887677665353211000000000582698656653478775664676543265541156655643476645423543211000000"},"ep10_197":{"who":"HARUKI","text":"I was wrong about him. So. Here is my hand.","mono":false,"off":672.698,"dur":2.347,"env":"19977854569887675687645665433336986543116877664277666534866532221100000"},"ep10_198":{"who":"RIN","text":"And here is my thread.","mono":false,"off":675.4447,"dur":1.259,"env":"05842389989975367866401137653320100000"},"ep10_199":{"who":"NEMU","text":"And here is me shouting. TAKUTO.","mono":false,"off":677.1033,"dur":2.496,"env":"005621498667644055534334544331332100000000000000000226400112886642321100000"},"ep10_200":{"who":"TAKUTO","text":"...I hear you. All of you.","mono":false,"off":679.9993,"dur":1.408,"env":"0006884248986547662088976522333211100000000"},"ep10_201":{"who":"TAKUTO","text":"Akuro. Not today.","mono":false,"off":681.8073,"dur":1.451,"env":"15740216965999853445553045423553211000000000"},"ep10_202":{"who":"AKURO","text":"...Hmph. You have too many friends, boy. It is very inconvenient.","mono":true,"off":683.658,"dur":5.333,"env":"0012499754245445789753113664555784211222125744588641012345778957842111499876666642103788866433210000247789853222246998888653125644311346522234566532232111001000"},"ep10_203":{"who":"HARUKI","text":"Frozen Hour! Three seconds!","mono":false,"off":689.3913,"dur":1.856,"env":"00018977765687546677666554113676652268621442222222000000"},"ep10_204":{"who":"SIEG","text":"Afterimage...! One more... for the road...","mono":false,"off":691.6473,"dur":2.539,"env":"06875203788778765554310000599766777766666663000000299687778867765444322100000"},"ep10_205":{"who":"TAKUTO","text":"Ruinbreaker!","mono":false,"off":694.586,"dur":0.981,"env":"013688877647986202553210000000"},"ep10_206":{"who":"CROWD","text":"They held! The Hunters held the bridge!","mono":false,"off":695.9673,"dur":2.411,"env":"0366653248998643100014211577512343222300144432242004543221000111000000000"},"ep10_207":{"who":"CROWD2","text":"Every village made it! Every one!","mono":false,"off":698.778,"dur":2.005,"env":"1798226652156666523223444433542000015882154324432110000000000"},"ep10_208":{"who":"SIEG","text":"...Fifteen. Sixteen. Haruki.","mono":false,"off":701.1833,"dur":2.219,"env":"0139631047665555200012276313310676665431012676666665311564332210000"},"ep10_209":{"who":"TAKUTO","text":"You are alive.","mono":false,"off":703.802,"dur":1.024,"env":"0136699888556877653211101000000"},"ep10_210":{"who":"SIEG","text":"I am counting. That means yes. Ow. Do not make me laugh. Ow.","mono":false,"off":705.226,"dur":3.989,"env":"078876752279666753386566410000006951399888755786666443331000288777664698875326873018767776655421110000000069975443321000"},"ep10_211":{"who":"RIN","text":"Four broken ribs, a broken arm, and something wrong with your leg that I do not want to name. I am stitching all of it.","mono":false,"off":709.6153,"dur":6.827,"env":"0011799983029896011777646778742134115201799730236542455655544311454536540056764487776665454011565446666521004335553025555555311344212235544433321000000000000000155677665344253025344431244444102200200000000"},"ep10_212":{"who":"SIEG","text":"This stupid family.","mono":false,"off":716.842,"dur":1.408,"env":"0797432320297741776542067666776554443210000"},"ep10_213":{"who":"RIN","text":"This stupid family.","mono":false,"off":718.65,"dur":1.259,"env":"05933330487404941006755555443322000000"},"ep10_214":{"who":"WICK","text":"We fought a Calamity. Rank F. Rank F, Takuto! Somebody tell the clerk!","mono":false,"off":720.3087,"dur":3.925,"env":"0562169957112766666667555543566641445542000000056662166631022685201642356544334446665754431415553230114432100000000000"},"ep10_215":{"who":"VESPER","text":"Error.","mono":false,"off":724.634,"dur":0.832,"env":"0021799997986655751000000"},"ep10_216":{"who":"TAKUTO","text":"Vesper.","mono":false,"off":725.866,"dur":0.747,"env":"00179854200776431100000"},"ep10_217":{"who":"VESPER","text":"Your axe went red. Then it went out. With a city behind you, and a Calamity in front of you.","mono":false,"off":727.0127,"dur":4.864,"env":"02796105665202320675213576543211000000378741376653455443200210000003614432227456514631135555542244332145440114656555555233224431115544310232222000"},"ep10_218":{"who":"VESPER","text":"I will write that in my letter. In those words. They may not believe me.","mono":false,"off":732.2767,"dur":3.819,"env":"0577357732686652000664232476655545555323322100000689738776532026443221022220000456666656552000544444421004332220000"},"ep10_219":{"who":"TAKUTO","text":"Thank you.","mono":false,"off":736.4953,"dur":0.832,"env":"0019987611168754321100000"},"ep10_220":{"who":"VESPER","text":"Do not thank me. Keep doing it. Every letter I write about you, I would like to be boring.","mono":false,"off":737.7273,"dur":4.885,"env":"048999776510000676410055443100123630003586655443210221000000018932466567775565424554256542231454320032233321355352146552000321343104544433222221000"},"ep10_221":{"who":"VALENTINE","text":"Sieg. You stubborn, magnificent idiot. Do you know how much I cried? Allergies. Entirely allergies.","mono":false,"off":743.0127,"dur":5.675,"env":"023377762003553432794066565555202786003442542105613333200100000011588988872226877650151431011355433331000000000019997885123333323114640221466655434334555444202222221221000"},"ep10_222":{"who":"SIEG","text":"I wrote you a letter, at the pass. In case. It said not to cry.","mono":false,"off":749.0873,"dur":4.16,"env":"06898886742127767677665676652001651373026766644333321000000002999622697666433220000001962335975588755421137313796544433321000"},"ep10_223":{"who":"VALENTINE","text":"Then I will cry twice as hard when I read it.","mono":false,"off":753.6473,"dur":2.645,"env":"04999868885860121677656402410587663524451115654332113444444325653132102100000000"},"ep10_224":{"who":"KUROZANE","text":"Valen. Get well. I want you at your best when I kill you.","mono":false,"off":756.6927,"dur":3.669,"env":"001178998666654313762124766654321000013442456521235663003431006553123100032322200111432221111110000000000000000"},"ep10_225":{"who":"SIEG","text":"You keep saying that. One day I will start to believe you.","mono":false,"off":760.762,"dur":3.413,"env":"0894139842133338766667775766653111000000000398766646766533566556533204776410277587667777642345432210000"},"ep10_226":{"who":"KUROZANE","text":"...Ha. That laugh. Still hate it.","mono":false,"off":764.5753,"dur":2.155,"env":"00223578984798423666654320012200444421134444122220000000000000000"},"ep10_227":{"who":"SIEG","text":"Takuto. You came back for me. On the bridge. I gave you an order.","mono":false,"off":767.13,"dur":4.139,"env":"02987511697533586665542000585129766764665410113777666531004777664238766643334431000000000037975486665567666412676533332210000"},"ep10_228":{"who":"TAKUTO","text":"You gave me a bad order.","mono":false,"off":771.6687,"dur":1.493,"env":"003323998415777522776665331356622221000000000"},"ep10_229":{"who":"SIEG","text":"...Ha. Ow. Yes. It was a terrible order. I have given a lot of terrible orders. Nobody ever ignored one before.","mono":false,"off":773.562,"dur":7.189,"env":"013776552005776665420047856542333332000000154696763042765564466410477763544430000000000048996527845555566555523630032665665466410477645543323320000000000079776575585100465456654368765665644446555543541114654322110000"},"ep10_230":{"who":"SIEG","text":"I counted you all, at the end. Did you know? Fifteen. Sixteen. I made it to sixteen. Eleven of them were already gone.","mono":false,"off":781.1513,"dur":7.467,"env":"06851249765525655776445665555541065114776544432000000000586688776655555552000000001696210288766553000000133396214420388876553000000479976666562114643327412430376554431000000001888875466665456666665566666546532276554332211000"},"ep10_231":{"who":"SIEG","text":"Five of them were standing over me when I woke up. That has never happened to me before.","mono":false,"off":789.018,"dur":5.035,"env":"00596666556555766555566443057766657653467656767766665100000078766666666651017753100000000000000004885398659976446654765204664327776535531128654321110000"},"ep10_232":{"who":"TAKUTO","text":"Get used to it.","mono":false,"off":794.4527,"dur":1.109,"env":"0039842357886441137655432000000000"},"ep10_233":{"who":"SIEG","text":"...I will try. It is harder than Morvudd.","mono":false,"off":795.962,"dur":2.581,"env":"177886676523535865566666520000004989875222376666577764576678777775354432210000"},"ep10_234":{"who":"HARUKI","text":"Sable told you. Didn't he? That he took me first.","mono":false,"off":798.9433,"dur":2.645,"env":"02437998578632329878654776643596777788766532012995774329305764117986422420100000"},"ep10_235":{"who":"TAKUTO","text":"You knew?","mono":false,"off":801.9887,"dur":0.725,"env":"0135678998764211000000"},"ep10_236":{"who":"HARUKI","text":"I saw him. In Lucien's study. Three times this year. I told myself he was a diplomat. A merchant. Anything.","mono":false,"off":803.114,"dur":5.824,"env":"2897433688987886553136776797643266643311875454431001487651327666666541265432154322100000000000002885338745766643287521365655643572046666553114766887403356420037776412321100000"},"ep10_237":{"who":"HARUKI","text":"Lucien caught me with gold when I fell. I never asked who pushed.","mono":false,"off":809.338,"dur":3.243,"env":"03698854366652238751366555211177655434655555210476432121003677776734776665442023631126322222010000"},"ep10_238":{"who":"TAKUTO","text":"Lucien is working with him.","mono":false,"off":812.9807,"dur":1.579,"env":"012698544366543432225995013444330033210000000000"},"ep10_239":{"who":"HARUKI","text":"I do not know. I do not know what is true anymore, Takuto. Except the bridge. The bridge was true.","mono":false,"off":814.9593,"dur":4.907,"env":"0796788875258777664237657787633677557465411328777676776666541318852118633465541035254397100653389874222321000000000486359886543356541132675311000000"},"ep10_240":{"who":"TAKUTO","text":"Then come with us. Not back to Lumen.","mono":false,"off":820.266,"dur":2.325,"env":"0068765124997787247753244320000047872039875100354345554432110000000000"},"ep10_241":{"who":"HARUKI","text":"I have to go back. The people in the Rite Hall. The grey hands. If I leave, nobody in there knows the truth.","mono":false,"off":822.9913,"dur":5.419,"env":"0788887203539853676652000540218620466666654577652111677643210165237876665357665321135320000000000028519886557666435777765356645556666666666655540142232653201100000"},"ep10_242":{"who":"TAKUTO","text":"...Then I go back with you.","mono":false,"off":828.81,"dur":1.387,"env":"000366666633993287652003411123221110000000"},"ep10_243":{"who":"HARUKI","text":"Of course you do. You never wait to be asked.","mono":false,"off":830.5967,"dur":2.325,"env":"0785113299997442587547665554577777854875676313454665577643224300010000"},"ep10_244":{"who":"LUCIEN","text":"Morvudd is dead. Valen lives. The Calamity stayed in the axe. And Haruki disobeyed me. Your plan failed, Sable.","mono":false,"off":833.322,"dur":6.869,"env":"037989735844643200486655210000168776665566675544322111220000034148888766665353332056665264555421365421002220003543278766763011443125333566521466552023221000000000282014966554100476655433310123256654112210000"},"ep10_245":{"who":"SABLE","text":"Failed? Morvudd was never meant to win. Morvudd was meant to make him angry. And look how angry he is.","mono":false,"off":840.5913,"dur":6.464,"env":"00011597555543311000122444223211246444441233323210231111222221110000000000001235563244212464343311332322100111111211111110000000000133433111133331122231111110012211111113443210000000000000000000"},"ep10_246":{"who":"SABLE","text":"Besides. Tyr is awake. And Tyr is walking toward your city.","mono":false,"off":847.4553,"dur":4.288,"env":"000469967888744321232113245443333332234422100000000000122223255344322134321011332111222211223442221122110000000000000000000000000"},"ep10_247":{"who":"TAKUTO","text":"Next time: Tyr, the Frost Titan, comes to Saint Lumen.","mono":false,"off":852.1433,"dur":3.477,"env":"026860340289998765530131577888752641115998534101267753033322100114766430134433554212455432211000000000000"},"ep10_248":{"who":"TAKUTO","text":"To save the city, I open the door all the way. I become the Crimson Calamity.","mono":false,"off":856.0207,"dur":5.035,"env":"02455449899511545443894443322455204796004655532056566663045777642354336665210000000000000003776335202487554511126655233444311344455654221110000000000000"},"ep10_249":{"who":"TAKUTO","text":"Vesper is ordered to kill me. And Nemu spends her eighth life.","mono":false,"off":861.4553,"dur":3.904,"env":"0015984410355555333035663542022001126544322100000000000014555555555555433410344433134300233320001246531100000000000000"},"ep10_250":{"who":"TAKUTO","text":"Episode eleven. Calamity.","mono":false,"off":865.7593,"dur":1.899,"env":"045113444998637534779523321100000115545665554221100000000"}}};
